import sys
from concurrent.futures import ThreadPoolExecutor

import pytest

MAX_WORKERS: int = 4
"""Number of threads sum_squares uses; read at call time."""


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Sum of square(x) for every x in xs, with the squares computed in
    parallel on a thread pool of MAX_WORKERS threads.

    The result is exact integer arithmetic and does not depend on the
    worker count or on the order in which workers finish. An empty list
    gives 0. The input list is not modified.
    """
    if not xs:
        return 0
    workers = max(1, MAX_WORKERS)
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def _set_workers(monkeypatch: pytest.MonkeyPatch, n: int) -> None:
    monkeypatch.setattr(sys.modules[__name__], "MAX_WORKERS", n)


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_big_ints_exact() -> None:
    big = 10**20
    assert sum_squares([big, -big, 1]) == 2 * big * big + 1


def test_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 64])
def test_same_result_at_every_worker_count(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    _set_workers(monkeypatch, workers)
    xs = list(range(-500, 500))
    assert sum_squares(xs) == sum(x * x for x in xs)


@pytest.mark.parametrize("workers", [1, 2, 8, 64])
def test_fewer_items_than_workers(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    _set_workers(monkeypatch, workers)
    assert sum_squares([2, 3]) == 13
    assert sum_squares([]) == 0


def test_repeated_calls_are_stable() -> None:
    xs = [5, -4, 3, 2, 1] * 100
    expected = sum(x * x for x in xs)
    assert all(sum_squares(xs) == expected for _ in range(20))
